// Aplati les resultats Apify et attache le compte cible
const items = $input.all();
const out = [];
for (const item of items) {
  const profiles = Array.isArray(item.json) ? item.json : [item.json];
  for (const p of profiles) {
    if (!p || !p.linkedinUrl) continue;
    out.push({ json: { ...p, targetAccountName: 'Enzo Vidiella', targetAccountId: 'rK6EsaFyRYG4xxssJ5X6vQ' } });
  }
}
return out;

// Scoring ICP Enzo sur 100 pts — ne garde que score >= 60
function parseDurationMonths(duration) {
  if (!duration) return 0;
  let months = 0;
  const yrMatch = duration.match(/(\d+)\s*yr/);
  const moMatch = duration.match(/(\d+)\s*mo/);
  if (yrMatch) months += parseInt(yrMatch[1], 10) * 12;
  if (moMatch) months += parseInt(moMatch[1], 10);
  return months;
}

function scoreProfile(p) {
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  const headline = (p.headline || p.summary || '').toLowerCase();
  const posTitle = (pos.position || '').toLowerCase();
  const desc = (pos.description || '').toLowerCase();
  const months = parseDurationMonths(pos.duration);

  // S1: fondateur/CEO + anciennete
  let s1 = 0;
  const isFounder = /founder|ceo|owner|president|co-founder/.test(posTitle) || /founder|ceo|owner/.test(headline);
  if (isFounder) s1 += 15;
  if (months >= 12) s1 += 15;
  else if (months >= 6) s1 += 7;

  // S2: secteur cible (SaaS, beauty, retail, fashion)
  let s2 = 0;
  const sectorKeywords = /saas|software|beauty|cosmetic|retail|fashion|apparel|ecommerce|e-commerce|dtc|d2c/;
  if (sectorKeywords.test(headline) || sectorKeywords.test(desc)) s2 += 20;

  // S3: signal d'achat fort — recrutement actif poste commercial/directeur Europe
  let s3 = 0;
  if (/hiring|we're hiring|job opening|now hiring/.test(desc)) s3 += 10;
  if (/europe sales|country manager europe|head of sales europe|eu expansion|expanding to europe|international expansion/.test(desc) || /europe sales|country manager europe/.test(headline)) s3 += 20;
  if (p.followerCount && p.followerCount > 1000) s3 += 5;

  // S4: signal d'expansion / nouveau marche (pas besoin d'un signal explicite France)
  let s4 = 0;
  if (/expand|expansion|new market|scaling|growth/.test(desc)) s4 += 15;

  const total = s1 + s2 + s3 + s4;
  return { total, s1, s2, s3, s4, months, isFounder };
}

const items = $input.all();
const out = [];
for (const item of items) {
  const p = item.json;
  const countryCode = (p.location && p.location.countryCode || '').toUpperCase();
  if (countryCode !== 'US' && countryCode !== 'CA') continue;
  const score = scoreProfile(p);
  if (score.total < 60) continue;
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  out.push({
    json: {
      id: p.id,
      name: (p.firstName || '') + ' ' + (p.lastName || ''),
      linkedinUrl: p.linkedinUrl,
      publicIdentifier: (p.linkedinUrl || '').match(/linkedin\.com\/in\/([^/?]+)/)?.[1] || '',
      headline: p.headline || p.summary || '',
      company: pos.companyName || '',
      companyLinkedinUrl: pos.companyLinkedinUrl || '',
      score: score.total,
      targetAccountName: p.targetAccountName,
      targetAccountId: p.targetAccountId
    }
  });
}
return out;

const key = "dAD+/okr.dhaKPu5eBrawhgUFEh/kT3rywp8+CujTZWOT+260gX0=";
const base = "https://api30.unipile.com:16068";
const results = [];

for (const item of $input.all()) {
  const p = item.json;
  let employeeCount = null;
  const companyPublicId = (p.companyLinkedinUrl || '').match(/linkedin\.com\/company\/([^/?]+)/)?.[1] || '';

  if (companyPublicId) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: base + '/api/v1/linkedin/company/' + companyPublicId + '?account_id=' + p.targetAccountId,
        headers: { 'X-API-KEY': key },
        json: true
      });
      employeeCount = resp.employee_count != null ? resp.employee_count : null;
    } catch (e) {
      employeeCount = null;
    }
  }

  // Proxy taille d'entreprise pour un CA minimum de 200k$ : au moins 2 employes
  // (en dessous, tres probablement sous le seuil de revenu et de budget requis)
  if (employeeCount === null || employeeCount < 2) continue;

  let sizeBonus = 0;
  if (employeeCount >= 10) sizeBonus = 15;
  else if (employeeCount >= 2) sizeBonus = 8;

  results.push({ json: { ...p, employeeCount, score: (p.score || 0) + sizeBonus } });
}

return results;

const key = "dAD+/okr.dhaKPu5eBrawhgUFEh/kT3rywp8+CujTZWOT+260gX0=";
const base = "https://api30.unipile.com:16068";
const accountId = 'rK6EsaFyRYG4xxssJ5X6vQ';

let sentIds = new Set();
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/api/v1/users/invite/sent?account_id=' + accountId + '&limit=200',
    headers: { 'X-API-KEY': key },
    json: true,
  });
  (resp.items || []).forEach(i => { if (i.invited_user_id) sentIds.add(i.invited_user_id); });
} catch (e) {}

const staticData = $getWorkflowStaticData('global');
staticData.triedIds = staticData.triedIds || {};
const now = Date.now();
const TWELVE_HOURS = 12 * 3600000;
for (const id of Object.keys(staticData.triedIds)) {
  if (now - staticData.triedIds[id] > TWELVE_HOURS) delete staticData.triedIds[id];
}
const triedRecently = new Set(Object.keys(staticData.triedIds));

const items = $input.all();
const fresh = items.filter(i => !sentIds.has(i.json.id) && !triedRecently.has(i.json.id));
fresh.sort((a, b) => (b.json.score || 0) - (a.json.score || 0));
const picked = fresh.slice(0, 16);

// Pre-calcule un instant d'envoi cible pour chacun, reparti uniformement entre maintenant et 19h00 New York,
// avec un jitter +/-20% pour eviter un pattern parfaitement regulier.
const nyNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
const endOfWindow = new Date(nyNow);
endOfWindow.setHours(19, 0, 0, 0);
const msRemaining = Math.max(endOfWindow.getTime() - nyNow.getTime(), 0);
const n = Math.max(picked.length, 1);
const baseIntervalMs = msRemaining / n;

let cursorMs = 0;
for (let idx = 0; idx < picked.length; idx++) {
  const jitterFactor = 0.8 + Math.random() * 0.4;
  cursorMs += baseIntervalMs * jitterFactor;
  picked[idx].json._waitSeconds = Math.min(Math.max(Math.round(cursorMs / 1000), 20), 39600);
}
if (picked.length) picked[0].json._runStartMs = Date.now();
for (let idx = 1; idx < picked.length; idx++) picked[idx].json._runStartMs = picked[0].json._runStartMs;

return picked;

const nyHour = parseInt(new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: 'numeric', hour12: false }).format(new Date()), 10);
if (nyHour < 8 || nyHour >= 19) {
  return [];
}
return [{ json: $input.item.json }];

const key = "dAD+/okr.dhaKPu5eBrawhgUFEh/kT3rywp8+CujTZWOT+260gX0=";
const base = "https://api30.unipile.com:16068";
const lead = $input.item.json;
const providerId = $json.id;
const accountId = 'rK6EsaFyRYG4xxssJ5X6vQ';

const RETRYABLE_STATUS = [422, 429, 500];
const MAX_ATTEMPTS = 3;

let lastError = null;
let sent = false;

for (let attempt = 1; attempt <= MAX_ATTEMPTS && !sent; attempt++) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/api/v1/users/invite',
      headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
      body: { provider_id: providerId, account_id: accountId },
      json: true,
    });
    sent = true;
  } catch (e) {
    lastError = e;
    const status = e.response?.statusCode || e.statusCode || e.status || 0;
    const quotaLikely = RETRYABLE_STATUS.includes(status);
    if (!quotaLikely || attempt === MAX_ATTEMPTS) break;
    const backoffMs = attempt === 1 ? 15000 : 45000;
    await new Promise(r => setTimeout(r, backoffMs));
  }
}

return [{
  json: {
    ...lead,
    _inviteSent: sent,
    _inviteSkippedReason: sent ? null : ('quota_or_error_status_' + (lastError?.response?.statusCode || lastError?.statusCode || 'unknown')),
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.triedIds = staticData.triedIds || {};
const lead = $('Boucle 1 lead a la fois').item.json;
if (lead && lead.id) {
  staticData.triedIds[lead.id] = Date.now();
}
return [{ json: $input.item.json }];

// Exclut tout profil signalant "Open to Work" — structure (badge Apify) ou texte (headline/summary/about).
function isOpenToWork(p) {
  if (p == null) return false;
  if (p.openToWork === true || p.open_to_work === true || p.isOpenToWork === true) return true;
  if (Array.isArray(p.badges) && p.badges.some(b => /open.?to.?work/i.test(String(b)))) return true;

  const fields = [p.headline, p.summary, p.about, p.title];
  const text = fields.filter(Boolean).join(' ').toLowerCase();
  const patterns = [
    /open\s*to\s*work/i,
    /#opentowork/i,
    /ouvert(e)?\s+aux\s+opportunit/i,
    /\u00e0\s+l['\u2019]\u00e9coute\s+du\s+march/i,
    /en\s+recherche\s+d['\u2019]emploi/i,
    /disponible\s+imm\u00e9diatement/i,
    /recherche\s+active(?:ment)?\s+un\s+poste/i,
  ];
  return patterns.some(re => re.test(text));
}

const items = $input.all();
return items.filter(item => !isOpenToWork(item.json));
